where e.category_id in (select id from stock_promote);
insert into public.generator_reachability_v16_2_7(category_id,difficulty,reachable,failure_stage,detail,audit_version,checked_at)
select e.category_id,p->>'difficulty',true,null,jsonb_build_object('witness',p->'witness','snapshotFingerprint',e.snapshot_fingerprint,'rulesVersion',e.rules_version,'archiveSha256','c5835418c18f9322e7decbd6800f93a216eaae3cdfa31acb08f0518c0c6d6853')::text,'geostats-v16.3.4-source-recovery-exact-replay',now()
from public.category_recovery_evidence_v16_3_4 e cross join lateral jsonb_array_elements(e.proofs) p where e.category_id in(select id from stock_promote)
on conflict(category_id,difficulty) do update set reachable=true,failure_stage=null,detail=excluded.detail,audit_version=excluded.audit_version,checked_at=excluded.checked_at;
select public.refresh_v16_2_runtime_catalog();
do $accept$ declare problems jsonb; begin
 if exists(select 1 from stock_baseline b left join public.category_runtime_review_v16_2 v on v.id=b.id where not coalesce(v.computed_playable_v16_2,false)) then raise exception 'Existing category regressed'; end if;
 select jsonb_agg(jsonb_build_object('id',v.id,'blockers',v.v16_2_blockers,'proofReady',public.category_recovery_ready_v16_3_4(v.id))) into problems from stock_promote p join public.category_runtime_review_v16_2 v on v.id=p.id where not v.computed_playable_v16_2 or not v.enabled or not v.eligible_daily;
 if problems is not null then raise exception 'Promotion failed: %',problems; end if;
 if (select count(*) from public.category_runtime_review_v16_2 where computed_playable_v16_2)<>414 then raise exception 'Expected exactly 414 categories'; end if;
 perform public.assert_v16_3_4_runtime_catalog();
end $accept$;
